sys_script_include.script:
var Cisco_Secure_Access_Create_Approval_Incidents_Public_Apps = Class.create();
Cisco_Secure_Access_Create_Approval_Incidents_Public_Apps.prototype = {
    initialize: function () {
    },

    createIncidentsForPublicApps: function () {
        gs.info("[Cisco Secure Access - PA] STEP 1: Starting createIncidentsForPublicApps()");
        try {
            var gr = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
            gr.addQuery('u_discovered_in', 'CSA');
            gr.addQuery('u_send_alert', 'No');
            gr.addQuery('u_status', 'Pending');
            gr.query();

            var totalApps = gr.getRowCount();
            gs.info("[Cisco Secure Access - PA] - Total public apps to process: " + totalApps);

            var processedCount = 0;

            while (gr.next()) {
                processedCount++;
                gs.info("[Cisco Secure Access - PA] - Processing app " + processedCount + " of " + totalApps + ": " + gr.u_app_name);

                // Create Incident
                var inc = new GlideRecord('incident');
                inc.initialize();
                inc.short_description = "[Cisco Secure Access - PA] - App Approval Required: " + gr.u_app_name;

                // Build telemetry string if sources exist
                var telemetryStr = "";
                if (gr.u_sources) {
                    var sources;
                    try {
                        sources = JSON.parse(gr.u_sources);
                    } catch (e) {
                        sources = [];
                    }
                    sources.forEach(function(src) {
                        if (src.name == 'cdfw')
                            telemetryStr += "CDFW - Events: " + src.events + ", Blocked: " + src.blockedEvents + "\n";
                        if (src.name == 'dns')
                            telemetryStr += "DNS - Requests: " + src.requests + ", Blocked Requests: " + src.blockedRequests + "\n";
                        if (src.name == 'swg')
                            telemetryStr += "SWG - Total Traffic: " + src.totalTraffic + ", Bytes In: " + src.bytesIn + ", Bytes Out: " + src.bytesOut + ", Blocked Out: " + src.blockedBytesOut + "\n";
                    });
                }

                inc.description =
                    "App ID: " + gr.u_app_id + "\n" +
                    "Name: " + gr.u_app_name + "\n" +
                    "Label: " + gr.u_label + "\n" +
                    "Weighted Risk: " + gr.u_weighted_risk + "\n" +
                    "Category: " + gr.u_category + "\n" +
                    "Subcategory: " + gr.u_subcategory + "\n" +
                    "Content Types: " + (gr.u_subcategory_content_types || "") + "\n" +
                    "App Type: " + gr.u_app_type + "\n" +
                    "First Detected: " + gr.u_first_detected + "\n" +
                    "Last Detected: " + gr.u_last_detected + "\n\n" +
                    "Telemetry:\n" + telemetryStr;

                // Assign to Nilesh (Sys ID)
                inc.assigned_to = '5208f945c363e210cb33514ed40131c6';
                inc.u_status = "Pending";

                var incSysId = inc.insert();
                gs.info("[Cisco Secure Access - PA] - Created Incident for App: " + gr.u_app_name + " (Incident Sys ID: " + incSysId + ")");

                // Update discovered application record
                gr.u_send_alert = "Yes";
                gr.u_status = "Pending";
                gr.update();
                gs.info("[Cisco Secure Access - PA] - Updated App: " + gr.u_app_name + " marked as incident sent.");
            }

            gs.info("[Cisco Secure Access - PA] - Completed processing " + processedCount + " public apps for approval incidents.");

        } catch (ex) {
            gs.error('[Cisco Secure Access - PA] - Error creating approval incidents: ' + ex.message);
            gs.error('[Cisco Secure Access - PA] - Error stack: ' + ex.stack);
        }
        gs.info("[Cisco Secure Access - PA] STEP 3: Finished createIncidentsForPublicApps()");
    },

    type: 'Cisco_Secure_Access_Create_Approval_Incidents_Public_Apps'
};
